template:
% 参数由系统自动注入：\def\radius{3} \def\anglea{60} \def\opdist{5} \def\showtangent{1} \def\showpoint{0} \def\showsecond{0} \def\showradius{1} \def\showline{0} \def\showequalmark{0} \def\showchord{0} \def\showangle{0} \def\showcentralangle{0} \def\showcenter{1} \def\labelta{A} \def\labeltb{B} \def\labelp{P}
% 第二条切线与连心线都必然经过 P，故只要画它们就一定要画出 P
\pgfmathsetmacro{\pshown}{max(\showpoint,\showsecond,\showline)}
% 切点位置：由 OA⊥PA 得 ∠AOP = arccos(radius/opdist)；切线长 PA = sqrt(OP^2 - r^2)
\pgfmathsetmacro{\tha}{acos(\radius/\opdist)}
\pgfmathsetmacro{\tlen}{sqrt(\opdist*\opdist - \radius*\radius)}
% 第二切点 B 与 A 关于连心线 OP 对称；OP 方向为 anglea - tha
\pgfmathsetmacro{\angleb}{\anglea - 2*\tha}
\pgfmathsetmacro{\axang}{\anglea - \tha}
% 视觉归一化：画出 P 时最宽跨度为圆最远端到 P，否则只有圆与切线，按直径归一
\pgfmathsetmacro{\extent}{\pshown > 0 ? (\radius + \opdist) : 2.4*\radius}
\pgfmathsetmacro{\figscale}{6 / \extent}
% 装饰尺寸：scale= 会同时缩放坐标和 pt 单位长度，故绝对尺寸除以 figscale 抵消，保证视觉大小恒定。
\pgfmathsetmacro{\dotr}{1.6/\figscale}
\pgfmathsetmacro{\loff}{0.34/\figscale}
\pgfmathsetmacro{\Ax}{\radius*cos(\anglea)}
\pgfmathsetmacro{\Ay}{\radius*sin(\anglea)}
\pgfmathsetmacro{\Bx}{\radius*cos(\angleb)}
\pgfmathsetmacro{\By}{\radius*sin(\angleb)}
% A 指向 P 的单位向量：OA⊥AP 且 P 在 A 的顺时针侧，故方向恒为 anglea-90（B 侧同理为 angleb+90）
\pgfmathsetmacro{\tax}{cos(\anglea-90)}
\pgfmathsetmacro{\tay}{sin(\anglea-90)}
\pgfmathsetmacro{\tbx}{cos(\angleb+90)}
\pgfmathsetmacro{\tby}{sin(\angleb+90)}
\pgfmathsetmacro{\Px}{\Ax + \tlen*\tax}
\pgfmathsetmacro{\Py}{\Ay + \tlen*\tay}
% 切线段越过切点的少量出头量；无 P 时切线画成直线，半长按半径成比例
\pgfmathsetmacro{\ovs}{0.15*\radius}
\pgfmathsetmacro{\llen}{1.1*\radius}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
  \coordinate (O) at (0,0);
  \coordinate (A) at (\Ax,\Ay);
  \coordinate (B) at (\Bx,\By);
  \coordinate (P) at (\Px,\Py);
  \draw[thick] (O) circle [radius=\radius];
  % 连心线 OP
  \ifnum\showline>0
    \draw[thick] (O) -- (P);
  \fi
  % 切点弦 AB（先画，避免压住切线）
  \ifnum\showsecond>0
    \ifnum\showchord>0
      \draw[thick] (A) -- (B);
    \fi
  \fi
  % 第一条切线：有 P 时画线段 PA，无 P 时画过 A 的整条直线 l
  \ifnum\showtangent>0
    \ifdim\pshown pt>0pt
      \draw[thick] (P) -- ({\Ax - \ovs*\tax},{\Ay - \ovs*\tay});
    \else
      \draw[thick] ({\Ax + \llen*\tax},{\Ay + \llen*\tay}) -- ({\Ax - \llen*\tax},{\Ay - \llen*\tay});
      \node at ({\Ax - 0.9*\llen*\tax + 0.14*\radius*cos(\anglea)},{\Ay - 0.9*\llen*\tay + 0.14*\radius*sin(\anglea)}) {$l$};
    \fi
  \fi
  % 第二条切线 PB
  \ifnum\showsecond>0
    \draw[thick] (P) -- ({\Bx - \ovs*\tbx},{\By - \ovs*\tby});
  \fi
  % 切点半径 + 直角记号（切线⊥切点半径）
  \ifnum\showradius>0
    \draw[thick] (O) -- (A);
    \pgfmathsetmacro{\rms}{min(0.26/\figscale, \radius*0.16, \tlen*0.16)}
    \draw[thick] ({\Ax - \rms*cos(\anglea)},{\Ay - \rms*sin(\anglea)}) -- ({\Ax - \rms*cos(\anglea) + \rms*\tax},{\Ay - \rms*sin(\anglea) + \rms*\tay}) -- ({\Ax + \rms*\tax},{\Ay + \rms*\tay});
    \ifnum\showsecond>0
      \draw[thick] (O) -- (B);
      \draw[thick] ({\Bx - \rms*cos(\angleb)},{\By - \rms*sin(\angleb)}) -- ({\Bx - \rms*cos(\angleb) + \rms*\tbx},{\By - \rms*sin(\angleb) + \rms*\tby}) -- ({\Bx + \rms*\tbx},{\By + \rms*\tby});
    \fi
  \fi
  \ifnum\showsecond>0
    % 切线长等长记号 PA=PB
    \ifnum\showequalmark>0
      \pgfmathsetmacro{\tk}{min(0.16/\figscale, \tlen*0.1)}
      \pgfmathsetmacro{\mpax}{\Ax + 0.5*\tlen*\tax}
      \pgfmathsetmacro{\mpay}{\Ay + 0.5*\tlen*\tay}
      \draw[thick] ({\mpax - \tk*\tay},{\mpay + \tk*\tax}) -- ({\mpax + \tk*\tay},{\mpay - \tk*\tax});
      \pgfmathsetmacro{\mpbx}{\Bx + 0.5*\tlen*\tbx}
      \pgfmathsetmacro{\mpby}{\By + 0.5*\tlen*\tby}
      \draw[thick] ({\mpbx - \tk*\tby},{\mpby + \tk*\tbx}) -- ({\mpbx + \tk*\tby},{\mpby - \tk*\tbx});
    \fi
    % 两切线夹角 ∠APB 的角弧：从 P 指向 A 的方向扫到 P 指向 B 的方向（取 360 内的短向）
    \ifnum\showangle>0
      \pgfmathsetmacro{\sangp}{\anglea + 90}
      \pgfmathsetmacro{\erawp}{\angleb - 90}
      \pgfmathsetmacro{\edifp}{\erawp - \sangp}
      \pgfmathsetmacro{\eangp}{\sangp + \edifp - 360*round(\edifp/360)}
      \pgfmathsetmacro{\arcp}{min(0.5/\figscale, \tlen*0.28)}
      \draw[thick] ({\Px + \arcp*cos(\sangp)},{\Py + \arcp*sin(\sangp)}) arc[start angle=\sangp, end angle=\eangp, radius=\arcp];
    \fi
    % 圆心角 ∠AOB 的角弧（朝 P 一侧，圆心角 = 2*tha < 180 故可直接从 anglea 扫到 angleb）
    \ifnum\showcentralangle>0
      \pgfmathsetmacro{\arco}{min(0.5/\figscale, \radius*0.3)}
      \draw[thick] ({\arco*cos(\anglea)},{\arco*sin(\anglea)}) arc[start angle=\anglea, end angle=\angleb, radius=\arco];
    \fi
  \fi
  % 切点与外点
  \fill (A) circle [radius=\dotr pt];
  \node at ({1.16*\Ax},{1.16*\Ay}) {$\labelta$};
  \ifnum\showsecond>0
    \fill (B) circle [radius=\dotr pt];
    \node at ({1.16*\Bx},{1.16*\By}) {$\labeltb$};
  \fi
  \ifdim\pshown pt>0pt
    \fill (P) circle [radius=\dotr pt];
    \node at ({\Px + \loff*cos(\axang)},{\Py + \loff*sin(\axang)}) {$\labelp$};
  \fi
  % 圆心 O：标注放在背离 P 的一侧，避免压住 OP 与两条切点半径
  \ifnum\showcenter>0
    \fill (O) circle [radius=\dotr pt];
    \node at ({0.17*\radius*cos(\axang+180)},{0.17*\radius*sin(\axang+180)}) {$O$};
  \fi
\end{tikzpicture}
